import re
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
from pathlib import Path

# ================================
# CONFIG
# ================================

OUTPUT_DIR = Path(r"C:\Users\Admin\OneDrive - The Ohio State University\RA\Output\Prelim")

K     = 5
N_REP = 30

outcome_vars = ["ln_gen_consumption_flag", "ln_total_farm_expense"]

# Human-readable labels for all individual drop columns.
# Combined drops are auto-generated by splitting on _AND_ and stacking lines.
drop_labels = {
    "__base__":                        "Baseline (full model)",
    "w_farm_size_agland":              "Farm size (agland)",
    "w_value_crop_production":         "Crop production value",
    "w_value_assets":                  "Household assets",
    "w_nonfarm_income":                "Non-farm income",
    "w_lvstck_holding_tlu":            "Livestock holdings (TLU)",
    "ag_plot_formal_rights_hh":        "Formal land rights",
    "income_shock":                    "Income shock",
    "food_shock":                      "Food shock",
    "price_shock":                     "Price shock",
    "head_maritial_status":            "HH head marital status",
    "head_age":                        "HH head age",
    "head_sex":                        "HH head sex",
    "member":                          "Household members",
    "adult_member":                    "Adult household members",
    "phone_access":                    "Phone access",
    "internet_access":                 "Internet access",
    "probability_moderately_insecure": "Food insecurity risk",
    "FCS_index":                       "Food consumption score",
    "non_farming_loan":                "Non-farm loan",
}

outcome_labels = {
    "ln_gen_consumption_flag": "Log consumption",
    "ln_total_farm_expense":   "Log farm expense",
}

COLORS = {
    "ln_gen_consumption_flag": "#185FA5",
    "ln_total_farm_expense":   "#0F6E56",
}

# ================================
# HELPERS
# ================================

def safe_outcome_label(y_col):
    return re.sub(r"[^A-Za-z0-9_]+", "_", str(y_col))

def load_csv(K, N_REP, y_col):
    y_lbl = safe_outcome_label(y_col)
    path  = OUTPUT_DIR / f"benchmark_K{K}_Rep{N_REP}_{y_lbl}.csv"
    if not path.exists():
        raise FileNotFoundError(f"CSV not found: {path}")
    return pd.read_csv(path, index_col="parameter")

def make_label(col):
    """
    For single drops: look up in drop_labels, fall back to raw name.
    For combined drops (contains _AND_): split, look up each part,
    stack vertically with ' +' at end of each line except the last.
    e.g. 'Non-farm income +\nHousehold assets +\nCrop production value'
    """
    if "_AND_" not in col:
        return drop_labels.get(col, col)
    parts = col.split("_AND_")
    resolved = [drop_labels.get(p.strip(), p.strip()) for p in parts]
    lines = [r + " +" for r in resolved[:-1]] + [resolved[-1]]
    return "\n".join(lines)

# ================================
# LOAD DATA
# ================================

dfs = {}
for y_col in outcome_vars:
    try:
        dfs[y_col] = load_csv(K, N_REP, y_col)
        print(f"Loaded: {y_col}")
    except FileNotFoundError as e:
        print(e)

# Discover all drop columns across all loaded CSVs
all_cols = set()
for df in dfs.values():
    all_cols.update(df.columns.tolist())
all_cols = ["__base__"] + sorted(all_cols - {"__base__"})

# Build rows
rows = []
for y_col, df in dfs.items():
    theta_base = float(df.loc["theta", "__base__"])
    for col in all_cols:
        if col not in df.columns:
            continue
        try:
            lo_adv = float(df.loc["bound_lower_adv", col])
            hi_adv = float(df.loc["bound_upper_adv", col])
            lo_emp = float(df.loc["bound_lower_emp", col])
            hi_emp = float(df.loc["bound_upper_emp", col])
            rho    = float(df.loc["rho", col]) if str(df.loc["rho", col]) not in ("", "nan") else np.nan
            delta  = float(df.loc["delta_theta", col])
        except (ValueError, KeyError):
            lo_adv = hi_adv = lo_emp = hi_emp = rho = delta = np.nan

        valid = not (np.isnan(lo_adv) or np.isnan(hi_adv))
        rows.append({
            "y_col":       y_col,
            "drop_lbl":    col,
            "theta":       theta_base,
            "lo_adv":      lo_adv,
            "hi_adv":      hi_adv,
            "lo_emp":      lo_emp,
            "hi_emp":      hi_emp,
            "rho":         rho,
            "valid":       valid,
            "delta_theta": delta,
        })

# Keep only columns with at least one valid bound — exclude baseline from plot rows
cols_with_bounds = {r["drop_lbl"] for r in rows if r["valid"]}
cols_to_plot = [
    c for c in all_cols if c != "__base__" and c in cols_with_bounds
]

# ================================
# SORT by avg |delta_theta| across outcomes (smallest to largest)
# ================================

def avg_abs_delta(col):
    deltas = [
        abs(r["delta_theta"])
        for r in rows
        if r["drop_lbl"] == col and not np.isnan(r["delta_theta"])
    ]
    return np.mean(deltas) if deltas else np.inf

bench_set_sorted = sorted(cols_to_plot, key=avg_abs_delta)

# Drop rows below the mean
mean_delta = np.median([avg_abs_delta(col) for col in bench_set_sorted])
bench_set_sorted = [col for col in bench_set_sorted if avg_abs_delta(col) >= mean_delta]

# ================================
# PLOT
# ================================

n_drops    = len(bench_set_sorted)
n_outcomes = len(outcome_vars)

# within_gap controls separation of the two outcome lines inside a group.
# group_gap controls space between different benchmark variable groups.
# Keep within_gap stable to avoid end-cap overlap; reduce group_gap to compress.
within_gap = 0.09
group_gap  = 0.18

# End caps scaled just under half of within_gap so they never overlap
cap_size = within_gap * 0.45

fig, ax = plt.subplots(figsize=(12, 0.42 * n_drops * n_outcomes + 1.8))
fig.patch.set_facecolor("white")
ax.set_facecolor("#F9F9F8")

yticks, yticklabels = [], []

for g_idx, col in enumerate(bench_set_sorted):
    y_center = -(g_idx * (n_outcomes * within_gap + group_gap))

    # Alternating row shading
    if g_idx % 2 == 0:
        ax.axhspan(
            y_center - (n_outcomes * within_gap) / 2 - 0.04,
            y_center + (n_outcomes * within_gap) / 2 + 0.04,
            color="#EBEBEA", zorder=0, linewidth=0
        )

    yticks.append(y_center)
    yticklabels.append(make_label(col))

    for o_idx, y_col in enumerate(outcome_vars):
        row = next(
            (r for r in rows if r["y_col"] == y_col and r["drop_lbl"] == col),
            None
        )
        if row is None:
            continue

        color = COLORS[y_col]
        y_pos = y_center + (o_idx - (n_outcomes - 1) / 2) * within_gap
        theta = row["theta"]

        if row["valid"]:
            # Adversarial bounds (rho=1) — faint wide bar with end caps
            ax.plot(
                [row["lo_adv"], row["hi_adv"]], [y_pos, y_pos],
                color=color, linewidth=1.8, alpha=0.35,
                solid_capstyle="round", zorder=2
            )
            ax.plot(
                [row["lo_adv"], row["lo_adv"]],
                [y_pos - cap_size, y_pos + cap_size],
                color=color, linewidth=1.2, alpha=0.5, zorder=2
            )
            ax.plot(
                [row["hi_adv"], row["hi_adv"]],
                [y_pos - cap_size, y_pos + cap_size],
                color=color, linewidth=1.2, alpha=0.5, zorder=2
            )
            # Empirical rho bounds — thicker, opaque
            ax.plot(
                [row["lo_emp"], row["hi_emp"]], [y_pos, y_pos],
                color=color, linewidth=2.2, alpha=0.85,
                solid_capstyle="round", zorder=3
            )
            # Diamond at theta
            ax.plot(
                theta, y_pos,
                marker="D", markersize=5, color=color,
                markeredgewidth=0, zorder=4
            )
        else:
            # No valid bounds — open diamond only
            ax.plot(
                theta, y_pos,
                marker="D", markersize=5, color=color,
                markerfacecolor="none", markeredgewidth=1.0,
                markeredgecolor=color, zorder=4, alpha=0.55
            )
            

# Baseline reference lines (dashed vertical) — kept as reference even though
# baseline row is excluded from the y-axis
for y_col in outcome_vars:
    base_row = next(
        (r for r in rows if r["y_col"] == y_col and r["drop_lbl"] == "__base__"),
        None
    )
    if base_row:
        ax.axvline(
            base_row["theta"], color=COLORS[y_col],
            linewidth=1.5, linestyle="--", alpha=0.4, zorder=1
        )

# Y-axis — horizontal multi-line labels, right-aligned
ax.set_yticks(yticks)
ax.set_yticklabels(yticklabels, fontsize=14, rotation=0, va="center", ha="right",
                   linespacing=1.4)
ax.tick_params(axis="y", length=0, pad=8)
ax.tick_params(axis="x", labelsize=13, length=3, color="#AAAAAA", width=1.5)
plt.xlabel(r"Agricultural Loan Average Treatment Effect ($\hat{\theta}$)", fontsize=17, labelpad=10)
ax.set_xlim(0, 0.2)

# Spines
for spine in ["top", "right", "left"]:
    ax.spines[spine].set_visible(False)
ax.spines["bottom"].set_color("#CCCCCC")
ax.spines["bottom"].set_linewidth(1.5)
ax.grid(axis="x", color="#AAAAAA", linewidth=1.5, zorder=0)

# Legend — top left corner
legend_elements = []
for y_col in outcome_vars:
    legend_elements.append(
        mpatches.Patch(
            facecolor=COLORS[y_col],
            label=outcome_labels.get(y_col, y_col),
            alpha=0.75
        )
    )
legend_elements += [
    plt.Line2D([0], [0], color="gray", linewidth=2.2, alpha=0.85,
               label=r"Empirical bounds ($\hat{\rho}^2$)"),
    plt.Line2D([0], [0], color="gray", linewidth=1.8, alpha=0.35,
               label=r"Conservative bounds ($\hat{\rho}^2=1$)"),
    plt.Line2D([0], [0], marker="D", color="gray", markersize=5,
               linestyle="None", label=r"$\hat{\theta}$ estimate"),
    plt.Line2D([0], [0], marker="D", color="gray", markersize=5,
               linestyle="None", markerfacecolor="none", markeredgewidth=1.0,
               label= r"$\hat{\theta}$ estimate (no valid bounds)"),
]
ax.legend(
    handles=legend_elements,
    loc="upper left",
    bbox_to_anchor=(0.01, 0.99),
    bbox_transform=ax.transAxes,
    fontsize=12, framealpha=0.92, edgecolor="#CCCCCC",
    borderpad=0.7, labelspacing=0.5
)

fig.suptitle("Sensitivity of Treatment Effects to Omitted Variables",
             fontsize=23, y=0.97, x=0.5, ha="center")
fig.text(0.5, 0.88, "Estimated via Observed Variable Benchmarking bounds",
         fontsize=19, ha="center")


plt.tight_layout(rect=[0, 0, 1, 0.93])

out_path = OUTPUT_DIR / f"sensitivity_forest_plot_K{K}_Rep{N_REP}.png"
plt.savefig(out_path, dpi=180, bbox_inches="tight", facecolor="white")
plt.show()
print(f"Saved to: {out_path}")